// app/app/coin-draw-centre.js — when the jackpot replay's centre becomes a craps battle.
//
// A purchase day's coin leg has no bonus-trait draw (audit 5790a946): it plays one closed craps
// battle, CoinDrawBattle, among up to fifty wallets drawn from the far-future queues. The centre
// is the replay's "bonus area", so on such a day it can open that battle — but ONLY for a viewed
// wallet that was drawn into it (a CoinDrawBattleRun of its own, bust included). Anyone else sees
// the centre exactly as before: the battle's paid runs are ordinary far-future coin winners.
// Jackpot days never carry a fill-draw battle, so they never reach this.

const FLIP_WEI = 10n ** 18n;

function normalAddress(value) {
  const address = String(value ?? '').trim().toLowerCase();
  return /^0x[0-9a-f]{40}$/.test(address) ? address : null;
}

function wei(value) {
  try { const amount = BigInt(value ?? 0); return amount > 0n ? amount : 0n; } catch { return 0n; }
}

/** Compact whole-FLIP figure for the centre's small caption (12.4K, 3.1M). */
export function compactCentreFlip(value) {
  const whole = wei(value) / FLIP_WEI;
  for (const [scale, suffix] of [[1_000_000_000n, 'B'], [1_000_000n, 'M'], [1_000n, 'K']]) {
    if (whole >= scale) {
      const tenths = (whole * 10n) / scale;
      return `${tenths / 10n}${tenths % 10n ? `.${tenths % 10n}` : ''}${suffix}`;
    }
  }
  return whole.toString();
}

/**
 * The centre's craps-battle model for `viewer` on a day whose roll-2 payload carried
 * `coinDrawBattle`, or null when the centre stays as it is.
 */
export function coinDrawCentreModel(battle, viewer) {
  if (!battle || battle.kind !== 'fill-draw' || !Array.isArray(battle.entrants) || battle.entrants.length === 0) return null;
  const player = normalAddress(viewer);
  if (!player) return null;
  const index = battle.entrants.findIndex((row) => normalAddress(row?.player) === player);
  if (index < 0) return null;
  const run = battle.entrants[index];
  const runs = battle.entrants.length;
  const pot = wei(battle.pot);
  const paid = wei(run.paid);
  const potWinner = normalAddress(battle.winner) === player;
  const outcome = potWinner ? 'POT WON' : paid > 0n ? `PAID ${compactCentreFlip(paid)}` : 'BUSTED';
  const caption = `CRAPS BATTLE · ${runs} RUN${runs === 1 ? '' : 'S'}${pot > 0n ? ` · POT ${compactCentreFlip(pot)} FLIP` : ''}`;
  return Object.freeze({
    key: battle.key ?? `coin-draw:${Number(battle.day)}`,
    day: Number(battle.day),
    index,
    player,
    runs,
    units: Number(run.units ?? 1),
    paid: paid.toString(),
    pot: pot.toString(),
    potWinner,
    outcome,
    caption,
    action: 'WATCH YOUR RUN',
    ariaLabel: `${caption}. You were drawn in: ${outcome.toLowerCase()}. Open the craps battle on your run.`,
  });
}
